{
 "kind": "sequence",
 "format": 1,
 "id": "seq_raptor_story",
 "name": "Raptor News: into each story",
 "set": "set_raptor_news",
 "roles": {
  "a": {
   "mark": "a",
   "label": "Anchor"
  },
  "b": {
   "mark": "b",
   "label": "Co-anchor"
  }
 },
 "wallText": "RAPTOR NEWS",
 "wallSub": "{headline}",
