  {
   "id": "a_lead",
   "if": [
    {
     "fact": "turn",
     "op": "=",
     "value": "a"
    },
    {
     "fact": "lead",
     "op": "has"
    }
   ],
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "a"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "a",
    "lines": [
     "Our top story tonight: {headline}.",
     "We start with this: {headline}. Pay attention.",
     "First, the one you need to hear: {headline}."
    ]
   },
   "gfx": [
    {
     "kind": "bug",
     "text": "Raptor News",
     "sub": "Live",
     "colour": "#e11d2a",
     "corner": "top-right",
     "at": 0,
     "for": 0
    },
    {
     "kind": "story",
     "tag": "Top story",
     "title": "Alert",
     "text": "{headline}",
     "colour": "#e11d2a",
     "side": "right",
     "at": 0.2,
     "for": 0
    },
